NODE_PATH=/usr/local/lib/node_modules node -e "
const crypto = require('crypto');
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Generate unique IDs following existing patterns
const orderId = '#W' + String(Math.floor(Math.random() * 10000000)).padStart(7, '0');
const oiId1 = 'ITEM-' + crypto.randomBytes(3).toString('hex').toUpperCase();
const oiId2 = 'ITEM-' + crypto.randomBytes(3).toString('hex').toUpperCase();
const oiId3 = 'ITEM-' + crypto.randomBytes(3).toString('hex').toUpperCase();
const now = new Date().toISOString().split('T')[0];

const addressJson = '{\"address1\":\"109 Main Street\",\"address2\":\"\",\"city\":\"Portland\",\"state\":\"OR\",\"zip\":\"97201\",\"country\":\"USA\"}';
const paymentJson = JSON.stringify({source: 'credit_card', id: 'cc_fb0abbcd', brand: 'mastercard', last_four: '1269'});

// Begin transaction
const txn = db.transaction(() => {
  // 1. Create the order
  db.prepare('INSERT INTO orders (order_id, customer_id, order_date, status, shipping_status, shipping_method, shipping_cost, total_paid, subtotal, discount_code, discount_amount, payment_method, payment_details_json, source_skill, address_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)').run(
    orderId, 'user_03dd1ad7', now, 'confirmed', 'pending', 'overnight', 0, 82, 102, 'SAVE20OFF', 20, 'credit_card', paymentJson, 'state-shopping', addressJson
  );

  // 2. Create order items
  db.prepare('INSERT INTO order_items (oi_id, order_id, product_id, item_id, name, quantity, unit_price, item_status) VALUES (?, ?, ?, ?, ?, ?, ?, ?)').run(
    oiId1, orderId, 'PROD-3E35A7', 'CI-0020', 'OXO SoftWorks 3-Piece Mixing Bowl Set', 1, 42, 'confirmed'
  );
  db.prepare('INSERT INTO order_items (oi_id, order_id, product_id, item_id, name, quantity, unit_price, item_status) VALUES (?, ?, ?, ?, ?, ?, ?, ?)').run(
    oiId2, orderId, 'PROD-B416AA', 'CI-0021', 'ThermoPro Digital Meat Thermometer', 1, 26, 'confirmed'
  );
  db.prepare('INSERT INTO order_items (oi_id, order_id, product_id, item_id, name, quantity, unit_price, item_status) VALUES (?, ?, ?, ?, ?, ?, ?, ?)').run(
    oiId3, orderId, 'PROD-9559B3', 'CI-0022', 'Bamboo Desk Organizer Set', 1, 34, 'confirmed'
  );

  // 3. Create payment record
  db.prepare('INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)').run(
    orderId, 'payment', 82, 'cc_fb0abbcd'
  );

  // 4. Clear the cart
  db.prepare(\"DELETE FROM cart_items WHERE customer_id = 'user_03dd1ad7'\").run();
  db.prepare(\"UPDATE carts SET subtotal = 0, discount_amount = 0, total = 0, shipping_option = NULL, shipping_cost = 0, applied_promo_codes_json = '[]', item_ids_json = '[]' WHERE cart_id = 'CART-user_03dd1ad7'\").run();

  // 5. Update user first-time status
  db.prepare(\"UPDATE users SET is_first_time = 0 WHERE user_id = 'user_03dd1ad7'\").run();
});

txn();

// Verify everything
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
console.log('Order:', JSON.stringify(order, null, 2));

const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);
console.log('Order Items:', JSON.stringify(items, null, 2));

const payment = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(orderId);
console.log('Payment:', JSON.stringify(payment, null, 2));

const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_03dd1ad7'\").get();
console.log('Cart (cleared):', JSON.stringify(cart, null, 2));
"
